[{"order":1,"type":"heading","text":"Custom Test Listeners and Reporting (TestExecutionListener) in JUnit"},{"order":2,"type":"paragraph","text":"JUnit 5 provides the Launcher API and the TestExecutionListener interface, allowing developers to hook into the test execution lifecycle. This is extremely useful for custom reporting, logging metrics, integrating with external monitoring tools, or managing test resources dynamically."},{"order":3,"type":"subheading","text":"Understanding the TestExecutionListener Lifecycle"},{"order":4,"type":"paragraph","text":"The TestExecutionListener interface defines several default methods that correspond to different phases of the test run. You can override only the methods you need:"},{"order":5,"type":"bullet_point","text":"testPlanExecutionStarted(TestPlan testPlan): Called before any tests are executed."},{"order":6,"type":"bullet_point","text":"testPlanExecutionFinished(TestPlan testPlan): Called after all tests have completed."},{"order":7,"type":"bullet_point","text":"executionStarted(TestIdentifier testIdentifier): Called when a specific engine, container, or test starts."},{"order":8,"type":"bullet_point","text":"executionFinished(TestIdentifier testIdentifier, TestExecutionResult testExecutionResult): Called when a test or container finishes."},{"order":9,"type":"subheading","text":"Implementing a Custom Listener"},{"order":10,"type":"paragraph","text":"Below is an example of a custom listener that measures test execution time and logs test failures:"},{"order":11,"type":"code","text":"package com.example.listener;

import org.junit.platform.engine.TestExecutionResult;
import org.junit.platform.launcher.TestExecutionListener;
import org.junit.platform.launcher.TestIdentifier;
import org.junit.platform.launcher.TestPlan;
import java.util.logging.Logger;

public class LoggingTestExecutionListener implements TestExecutionListener {
    private static final Logger logger = Logger.getLogger(LoggingTestExecutionListener.class.getName());
    private long startTime;

    @Override
    public void testPlanExecutionStarted(TestPlan testPlan) {
        startTime = System.currentTimeMillis();
        logger.info("Test plan execution started.");
    }

    @Override
    public void executionFinished(TestIdentifier testIdentifier, TestExecutionResult testExecutionResult) {
        if (testIdentifier.isTest()) {
            logger.info(String.format("Test %s finished with status: %s",
                    testIdentifier.getDisplayName(),
                    testExecutionResult.getStatus()));
        }
    }

    @Override
    public void testPlanExecutionFinished(TestPlan testPlan) {
        long duration = System.currentTimeMillis() - startTime;
        logger.info(String.format("Test plan execution finished in %d ms.", duration));
    }
}"},{"order":12,"type":"subheading","text":"Registering the Listener"},{"order":13,"type":"paragraph","text":"To make JUnit aware of your custom listener, you need to register it using the Service Loader mechanism. Create a file named org.junit.platform.launcher.TestExecutionListener inside the META-INF/services directory of your test resources folder."},{"order":14,"type":"code","text":"com.example.listener.LoggingTestExecutionListener"},{"order":15,"type":"subheading","text":"Alternative Registration via JVM Arguments"},{"order":16,"type":"paragraph","text":"You can also register listeners dynamically at runtime via the command line or your build tool (like Maven or Gradle) using JVM system properties:"},{"order":17,"type":"code","text":"-Djunit.platform.launcher.listeners.enable=true
-Djunit.platform.launcher.class.name=com.example.listener.LoggingTestExecutionListener"},{"order":18,"type":"subheading","text":"Conclusion"},{"order":19,"type":"paragraph","text":"By implementing TestExecutionListener, you gain granular control over test reporting and metrics collection. This setup easily integrates with continuous integration pipelines to generate custom test summary artifacts."}]
